    <!-- Use Canvas.Right and Canvas.Bottom for right/bottom anchoring -->
    <Border Canvas.Right=""20"" Canvas.Bottom=""20""
            Width=""90"" Height=""60""
            Background=""#179842"" CornerRadius=""4"">
        <TextBlock Text=""Bottom-Right""
                   Foreground=""#FFFFFF""
