    Description = ""Create a new document"",
    ApplicationPath = Environment.ProcessPath,
    Arguments = ""--new"",
    CustomCategory = ""Tasks""
});

JumpList.SetJumpList(Application.Current, jumpList);

// Set taskbar progress indicator
