    public override string CSharpExample => @"using Jalium.UI.Input;
using StringRelayCommand =
    Jalium.UI.Gallery.Core.Mvvm.RelayCommand<string>;

public sealed class StandardCommandsViewModel : ViewModelBase
{
    private string _status = ""No command executed yet."";

    public StandardCommandsViewModel()
    {
        var execute = new StringRelayCommand(label =>
            Status = $""Executed: {label ?? ""Unknown""}"");
        var command = new StandardUICommand(StandardUICommandKind.Cut)
        {
            // Label, IconSource, Description, and Ctrl+X come from Kind.
            Command = execute
        };
        var shortcut = command.KeyboardAccelerators
            .OfType<KeyGesture>()
            .First()
            .GetDisplayStringForCulture(null);
        Cut = new StandardCommandItem(command, shortcut);
    }

    public StandardCommandItem Cut { get; }

    public string Status
    {
        get => _status;
        private set => SetProperty(ref _status, value);
    }
}

public sealed record StandardCommandItem(
    StandardUICommand Command,
    string KeyboardShortcut);";
}

