MainTerminal.Clear();
MainTerminal.StartShell();

// Write ANSI-colored text to read-only terminal
DemoTerminal.WriteLine(
    ""\x1b[1;36m=== Demo ===\x1b[0m"");
DemoTerminal.WriteLine(
    ""\x1b[1mBold\x1b[0m and \x1b[3mItalic\x1b[0m"");

// 256-color output
