    DemoTerminal.Write(
        $""\x1b[38;5;{i}m\u2588\x1b[0m"");

// True-color gradient
for (int i = 0; i < 60; i++)
{
    int r = (int)(255 * (1.0 - i / 60.0));
    int g = (int)(255 * (i / 60.0));
    DemoTerminal.Write(
        $""\x1b[38;2;{r};{g};128m\u2588\x1b[0m"");
}";
