public sealed partial class ViewboxViewModel
{
    public override string XamlExample => @"<Page xmlns=""http://schemas.jalium.ui/2024""
      xmlns:x=""http://schemas.microsoft.com/winfx/2006/xaml"">

    <!-- Uniform Stretch: scales preserving aspect ratio -->
    <Border BorderBrush=""#3D3D3D"" BorderThickness=""1"" Width=""150"" Height=""100"">
        <Viewbox Stretch=""Uniform"">
            <Button Content=""Scale Me"" Width=""200"" Height=""50""/>
        </Viewbox>
    </Border>

    <!-- Stretch Modes Comparison -->
    <StackPanel Orientation=""Horizontal"" Margin=""0,16,0,0"">
        <!-- None: no scaling applied -->
        <Border BorderBrush=""#3D3D3D"" BorderThickness=""1""
                Width=""100"" Height=""80"" Margin=""0,0,16,0"">
            <Viewbox Stretch=""None"">
                <Ellipse Width=""60"" Height=""40"" Fill=""#0078D4""/>
            </Viewbox>
        </Border>

        <!-- Fill: stretches to fill, ignoring aspect ratio -->
        <Border BorderBrush=""#3D3D3D"" BorderThickness=""1""
                Width=""100"" Height=""80"" Margin=""0,0,16,0"">
            <Viewbox Stretch=""Fill"">
                <Ellipse Width=""60"" Height=""40"" Fill=""#00CC6A""/>
            </Viewbox>
        </Border>

        <!-- Uniform: fits inside while preserving ratio -->
        <Border BorderBrush=""#3D3D3D"" BorderThickness=""1""
                Width=""100"" Height=""80"" Margin=""0,0,16,0"">
            <Viewbox Stretch=""Uniform"">
                <Ellipse Width=""60"" Height=""40"" Fill=""#F7630C""/>
            </Viewbox>
        </Border>

        <!-- UniformToFill: fills while preserving ratio (may clip) -->
        <Border BorderBrush=""#3D3D3D"" BorderThickness=""1""
                Width=""100"" Height=""80"" ClipToBounds=""True"">
            <Viewbox Stretch=""UniformToFill"">
                <Ellipse Width=""60"" Height=""40"" Fill=""#E81123""/>
            </Viewbox>
        </Border>
    </StackPanel>

    <!-- StretchDirection: control scale up/down behavior -->
    <StackPanel Orientation=""Horizontal"" Margin=""0,16,0,0"">
        <Border BorderBrush=""#3D3D3D"" BorderThickness=""1""
                Width=""120"" Height=""80"" Margin=""0,0,16,0"">
            <Viewbox Stretch=""Uniform"" StretchDirection=""UpOnly"">
                <TextBlock Text=""Small"" FontSize=""8"" Foreground=""#0078D4""/>
            </Viewbox>
        </Border>
        <Border BorderBrush=""#3D3D3D"" BorderThickness=""1""
                Width=""60"" Height=""40"" Margin=""0,0,16,0"">
            <Viewbox Stretch=""Uniform"" StretchDirection=""DownOnly"">
                <TextBlock Text=""Large"" FontSize=""24"" Foreground=""#00CC6A""/>
            </Viewbox>
        </Border>
        <Border BorderBrush=""#3D3D3D"" BorderThickness=""1""
                Width=""100"" Height=""60"">
            <Viewbox Stretch=""Uniform"" StretchDirection=""Both"">
                <TextBlock Text=""Both"" FontSize=""16"" Foreground=""#F7630C""/>
            </Viewbox>
        </Border>
    </StackPanel>
</Page>";

}

public sealed partial class WebViewViewModel
{
    public override string XamlExample => """
        <!-- WebView with address bar -->
        <StackPanel Orientation="Horizontal">
            <Button x:Name="BackButton" ToolTip="Back" Width="40" Height="40">
                <SymbolIcon Symbol="Back"/>
            </Button>
            <Button x:Name="ForwardButton" ToolTip="Forward" Width="40" Height="40">
                <SymbolIcon Symbol="Forward"/>
            </Button>
            <Button x:Name="RefreshButton" ToolTip="Refresh" Width="40" Height="40">
                <SymbolIcon Symbol="Refresh"/>
            </Button>
            <TextBox x:Name="AddressBar" Width="600"/>
            <Button x:Name="GoButton" Content="Go" Width="48"/>
        </StackPanel>

        <!-- WebView container -->
        <Border x:Name="WebViewContainer"
                Height="500"
                Background="#0D0D0D"
                CornerRadius="4"
                ClipToBounds="True"/>

        <!-- JavaScript execution -->
        <TextBox x:Name="ScriptInput" Height="32"/>
        <Button x:Name="ExecuteScriptButton" Content="Execute"/>
        <TextBlock x:Name="ScriptResultText" Text="Result: "/>
        """;

    public override string CSharpExample => """
        using Jalium.UI.Controls;

        // Create and configure WebView
        var webView = new WebView
        {
            Source = new Uri("https://www.bing.com")
        };
        container.Child = webView;

        // Initialize WebView2
        await webView.EnsureCoreWebView2Async();

        // Navigation
        webView.Navigate("https://example.com");
        webView.GoBack();
        webView.GoForward();
        webView.Refresh();

        // Handle events
        webView.NavigationStarting += (s, e) =>
        {
            addressBar.Text = e.Uri.AbsoluteUri;
        };
        webView.NavigationCompleted += (s, e) =>
        {
            status.Text = e.IsSuccess
                ? $"Loaded (HTTP {e.HttpStatusCode})"
                : "Navigation failed";
        };
        webView.DocumentTitleChanged += (s, e) =>
        {
            titleText.Text = e.Title;
        };

        // Execute JavaScript
        var result = await webView.ExecuteScriptAsync("document.title");

        // Cleanup
        webView.Dispose();
        """;
}

